async function* planePages(context, path, dependencies, label) {
  let cursor = null;
  const seen = new Set;
  for (let page = 0;page < TRACKER_DISCOVERY_LIMIT; page += 1) {
    const separator = path.includes("?") ? "&" : "?";
    const query = cursor === null ? `${separator}per_page=100` : `${separator}per_page=100&cursor=${encodeURIComponent(cursor)}`;
    const value = await requestJson(dependencies, {
      method: "GET",
      url: planeUrl(context, `${path}${query}`),
      headers: context.headers
    }, [200], context.secrets);
    if (Array.isArray(value)) {
      for (const item of value)
        yield item;
      return;
    }
    const envelope = record2(value, label);
    if (!Array.isArray(envelope.results)) {
      throw new EmpiricalError("TRACKER_MALFORMED_RESPONSE", `${label} results are missing or malformed`);
    }
    for (const item of envelope.results)
      yield item;
    if (typeof envelope.next_page_results !== "boolean") {
      throw new EmpiricalError("TRACKER_MALFORMED_RESPONSE", `${label} pagination flag is missing or malformed`);
    }
    const nextCursor = envelope.next_cursor;
    if (envelope.next_page_results === false) {
      if (nextCursor !== null && nextCursor !== "" && nextCursor !== undefined) {
        throw new EmpiricalError("TRACKER_MALFORMED_RESPONSE", `${label} has a terminal page with a next cursor`);
      }
      return;
    }
    if (typeof nextCursor !== "string" || nextCursor === "" || seen.has(nextCursor)) {
      throw new EmpiricalError("TRACKER_DISCOVERY_INCOMPLETE", `${label} pagination did not provide a new cursor`);
    }
    seen.add(nextCursor);
    cursor = nextCursor;
  }
  throw new EmpiricalError("TRACKER_RECONCILIATION_LIMIT", `${label} exceeded the bounded pagination limit`);
}
