      throw new EmpiricalError("DOCTOR_FIX_CHOICE_INVALID", `No plan entry ${choice.entry}`);
    if (chosen.has(entry2.id))
      throw new EmpiricalError("DOCTOR_FIX_CHOICE_INVALID", `Entry ${entry2.id} has more than one choice`);
    const option2 = entry2.actions.find((candidate2) => candidate2.id === choice.option);
    if (!option2)
      throw new EmpiricalError("DOCTOR_FIX_CHOICE_INVALID", `Entry ${entry2.id} has no option ${choice.option}`);
    if (!option2.executable) {
      throw new EmpiricalError("DOCTOR_FIX_CHOICE_INVALID", `Option ${choice.option} of ${entry2.id} is not run by doctor-fix; call ${option2.operation} with the user`);
    }
