  server.registerTool(operationName("qa-approve"), {
    title: "Record an explicit full-suite approval",
    description: operationSummary("qa-approve"),
    inputSchema: {
      root: exports_external.string().optional(),
      revision: exports_external.number().int().nonnegative(),
      commandId: exports_external.string().regex(/^[a-z][a-z0-9-]*$/),
      estimateMs: exports_external.number().int().nonnegative().nullable()
    },
    annotations: operationAnnotations("qa-approve")
  }, async ({ root, revision, commandId, estimateMs: estimateMs2 }) => toolResult(async () => {
    const project = await openWritableProject(root ?? defaultRoot);
    const elicitation = server.server.getClientCapabilities()?.elicitation;
    if (!isRecord7(elicitation)) {
      return project.qaApprove({ revision, commandId, estimateMs: estimateMs2, confirmation: "agent-relayed" });
    }
    if (Object.keys(elicitation).length > 0 && !isRecord7(elicitation.form)) {
      throw new EmpiricalError("FULL_SUITE_APPROVAL_FORM_REQUIRED", "This host advertises elicitation without form support, so the approval cannot be relayed; ask the user to approve through a form-capable host or the interactive CLI");
    }
    const request = await project.qaApprovalRequest({ revision, commandId, estimateMs: estimateMs2 });
    const estimate = request.estimateMs === null ? "estimate unknown" : `~${formatDuration(request.estimateMs)}`;
    const reason = request.route.reasons[0]?.code ?? "no local-forcing reason";
    const answer = await server.server.elicitInput({
      mode: "form",
      message: `Run full suite ${request.commandId} at rev ${request.revision} (${estimate})? Reason: ${request.route.route} route, ${reason}.`,
      requestedSchema: {
        type: "object",
        properties: { approve: { type: "boolean", title: "Run the full suite", description: "Approve this exact local full-suite run" } },
        required: ["approve"]
      }
    });
    if (answer.action !== "accept" || !isRecord7(answer.content) || answer.content.approve !== true) {
      throw new EmpiricalError("APPROVAL_DECLINED", `The user did not approve full suite ${request.commandId} at revision ${request.revision}; nothing was recorded`);
    }
    return project.qaApprove({ revision, commandId, estimateMs: estimateMs2, confirmation: "elicited" });
  }));
