      const planDigest = takeOption(context.args, "--plan-digest");
      const actor = takeOption(context.args, "--actor") ?? "user";
      const preview = takeFlag(context.args, "--preview");
      const yes = takeFlag(context.args, "--yes");
      assertNoArgs(context.args, "reconcile");
      const excluded = exclude === undefined ? [] : exclude.split(",").map((entry2) => entry2.trim()).filter(Boolean);
      if (excluded.some((feature2) => !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(feature2))) {
        throw new EmpiricalError("INVALID_ARGUMENT", "--exclude takes a comma-separated list of feature ids");
      }
      if (planDigest !== undefined && !/^sha256:[a-f0-9]{64}$/.test(planDigest)) {
        throw new EmpiricalError("INVALID_ARGUMENT", "--plan-digest requires the digest from the exact reconcile preview");
      }
      const project = await EmpiricalProject.open(context.root, { selection: "selected" });
      const base = { exclude: excluded, actor };
