function renderClosurePlan(plan) {
  const heading = plan.mode === "feature" ? `Force-close ${plan.feature} at revision ${plan.revision} (approval required)` : `Force-advance ${plan.feature} at revision ${plan.revision} (approval required)`;
  const lines = [
    heading,
    `Phase: ${plan.fromPhase} -> ${plan.toPhase}`,
    ...plan.outcome === null ? [] : [`Outcome: ${plan.outcome}`],
    `Completion stays: ${plan.completion}`,
    `Reason: ${plan.reason}`,
    ...plan.pendingPaths?.length ? ["Uncommitted paths (resolve before closure):", ...plan.pendingPaths.map((path) => `- ${JSON.stringify(path)}`)] : [],
    "",
    "This will:",
    ...plan.effects.map((effect) => `- ${effect}`)
  ];
  if (plan.externalMerge !== null) {
    lines.push("", "Observed external merge:", `- pull request #${plan.externalMerge.pullRequest} (${plan.externalMerge.url})`, `- merge commit ${plan.externalMerge.mergeCommit}, an ancestor of ${plan.externalMerge.targetBranch}`, "- these facts are recorded; they are not a delivery receipt and do not make the feature delivered");
  }
  return lines.join(`
`);
}
function renderCleanupPlan(plan) {
  const lines = [
    `Cleanup plan for ${plan.root} (approval required)`,
    `Classes: ${plan.include.join(", ")}`,
    ""
  ];
  if (plan.entries.length === 0) {
    lines.push("Nothing to prune: the current Doctor report names no orphan in these classes.");
  } else {
    lines.push("This will remove:");
    for (const entry2 of plan.entries) {
      lines.push(`- [${entry2.finding}] ${entry2.path ?? entry2.action}: ${entry2.detail}`);
    }
  }
  if (plan.refused.length > 0) {
    lines.push("", "Deliberately left alone:");
    for (const refusal of plan.refused) {
      lines.push(`- [${refusal.finding}] ${refusal.path ?? "(no single path)"}: ${refusal.reason}`);
    }
  }
  lines.push("", "Journals, receipts, specifications and policy are never touched.");
  return lines.join(`
`);
}
